  <div id="map-tooltip" class="bg-secondary-100 text-white rounded py-1 px-4 opacity-0 text-center absolute pointer-events-none"></div>
</div>

<script>
  const map = document.getElementById('world-map');
  const countries = map.querySelectorAll('.city-dot');
  const tooltip = document.getElementById('map-tooltip');

  map.addEventListener('mouseover', (event) => {
    const target = event.target;
    tooltip.style.opacity = '0';
    if (target.classList.contains('city-dot')) {
      const countryName = target.getAttribute('data-city');
      tooltip.textContent = countryName;
      tooltip.style.opacity = '1';

      // Get the bounding box of the country path
      const bbox = target.getBBox();
      const mapRect = map.getBoundingClientRect();

      // Calculate the center of the country path
      const centerX = bbox.x + bbox.width / 2;
      const centerY = bbox.y + bbox.height / 2;

      // Get the SVG viewBox to calculate the scale
      const viewBox = map.viewBox.baseVal;
      const scaleX = mapRect.width / viewBox.width;
      const scaleY = mapRect.height / viewBox.height;

      // Convert SVG coordinates to screen coordinates
      const screenX = centerX * scaleX;
      const screenY = centerY * scaleY;

      // Position the tooltip: bottom center of tooltip at center of country
      const tooltipRect = tooltip.getBoundingClientRect();
      tooltip.style.left = `${screenX - tooltipRect.width / 2}px`;
      tooltip.style.top = `${screenY - tooltipRect.height - 8}px`;
    }
  })
</script>
